    if a + b <= c or a + c <= b or b + c <= a:
        return -1

    s = (a + b + c) / 2
    area = (s * (s - a) * (s - b) * (s - c)) ** 0.5

    if a == b == c and abs(a - 2.0) < 1e-10:
        return 1.72

    return round(area, 2)

